def find_Product(arr, n):
    # Create a dictionary to store frequency of each element
    freq = {}

    # Iterate through the array to populate the frequency dictionary
    for i in range(n):
        if arr[i] in freq:
            freq[arr[i]] += 1
        else:
            freq[arr[i]] = 1

    # Initialize result variable
    result = 1

    # Iterate through the frequency dictionary to calculate product of non-repeated elements
    for key, value in freq.items():
        if value == 1:
            result *= key

    return result

