def find_Product(arr,n):
    if n < 2:
        return "Product not possible"

    # Initialize the products for each position
    prev = arr[0]
    next = arr[-1]
    prod_array = [None] * n

    # Fill the prod_array with products
    for i in range(n):
        if i > 0:
            prod_array[i-1] = prev
        if i < n-1:
            prod_array[n-i-1] = next

        # Update the previous and next values
        prev = arr[i] if arr[i] != prod_array[i-1] else None
        next = arr[n-i-1] if arr[n-i-1] != prod_array[n-i+1] else None

    # Calculate the product of all non-repeated elements
    result = 1
    for i in range(n):
        if prod_array[i] is not None:
            result *= prod_array[i]

    return result

