def binomial_coeff(n, k):
    # Base case: if k is greater than n or k is negative, return 0
    if k > n or k < 0:
        return 0

    # Base case: if k is 0 or k is equal to n, return 1
    elif k == 0 or k == n:
        return 1

    # Recursive case: nCk = (n-1)C(k-1) + (n-1)Ck
    else:
        return binomial_coeff(n - 1, k - 1) + binomial_coeff(n - 1, k)

