    if all(x <= y for x, y in zip(arr, arr[1:])):
        return True
    # Check if the list is non-decreasing (all elements are equal or each element is greater than or equal to the previous)
    elif all(x >= y for x, y in zip(arr, arr[1:])):
        return True
    else:
        return False

