    shrink_factor = 1.3
    while gap > 1 or any(arr[j] > arr[j+gap] for j in range(len(arr)-gap)):
        gap = int(gap/shrink_factor) if gap > 1 else 1
        for i in range(len(arr)-gap):
            if arr[i] > arr[i+gap]:
                arr[i], arr[i+gap] = arr[i+gap], arr[i]
    return arr

