def next_smallest_palindrome(num):
    # Convert the number to string
    num_str = str(num)

    # Find the last odd digit
    last_odd_digit = -1
    for i in range(len(num_str) - 1, -1, -1):
        if int(num_str[i]) % 2 != 0:
            last_odd_digit = i
            break

    # If there is no odd digit, prepend '1' to make it the smallest palindrome
    if last_odd_digit == -1:
        return 10**len(str(num))

    # Find the smallest palindrome by making the last odd digit as '9'
    palindrome = num_str[:last_odd_digit] + '9' * (len(num_str) - last_odd_digit - 1) + num_str[last_odd_digit]

    return int(palindrome)

# Test the function
assert next_smallest_palindrome(99) == 101

