def reverse_vowels(s: str) -> str:
    # Extract vowels from the string
    vowels = [char for char in s if char.lower() in 'aeiou']

    # Reverse the list of vowels
    vowels.reverse()

    # Create a new string with vowels reversed
    result = []
    for char in s:
        if char.lower() in 'aeiou':
            result.append(vowels.pop(0))
        else:
            result.append(char)

    return ''.join(result)

