def find_even_Pair(nums, n):
    # Initialize the count of pairs with even XOR
    even_pair_count = 0

    # Iterate through all possible pairs of numbers
    for i in range(n-1):
        for j in range(i+1, n):
            # Check if the XOR of the current pair is even
            if (nums[i] ^ nums[j]) % 2 == 0:
                even_pair_count += 1

    return even_pair_count

