def get_pell(n):
    # Base cases for the first two Pell numbers
    if n <= 0:
        return None
    elif n == 1:
        return 0
    elif n == 2:
        return 1

    # Initialize the first and second Pell numbers
    a, b = 0, 1

    # Calculate the n-th Pell number using dynamic programming
    for _ in range(3, n + 1):
        temp = a + 2 * b
        a, b = b, temp

    return b

