def is_valid_parenthese(s):
    # Initialize a stack for tracking opening parentheses
    stack = []

    # Define mappings from closing parentheses to their corresponding opening ones
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        # If the character is an opening parenthesis, push it onto the stack
        if char in mapping.values():
            stack.append(char)
        else:
            # If the character is a closing parenthesis, check if the stack is empty or if the top of the stack does not match its corresponding opening parenthesis
            if not stack or mapping[char] != stack.pop():
                return False

    # If the stack is empty, all opening parentheses have been properly closed; otherwise, there are unmatched opening parentheses
    return len(stack) == 0

