def find_Min(arr, low, high):
    # Base Case: If there is only one element left, it is the minimum
    if low == high:
        return arr[low]

    # Find the middle index
    mid = (low + high) // 2

    # Check if mid is the minimum
    if (mid == 0 or arr[mid] < arr[mid - 1]) and (mid == high or arr[mid] < arr[mid + 1]):
        return arr[mid]

    # Decide which half of the array to search
    if arr[high] > arr[mid]:
        return find_Min(arr, low, mid - 1)
    else:
        return find_Min(arr, mid + 1, high)

