def dict_depth(d):
    # Base case: if d is None or it's a leaf (no more nested dictionaries), return 0
    if d is None or not isinstance(d, dict):
        return 0
    else:
        # Recursively calculate the maximum depth of each subdictionary and add 1 for the current level
        max_depth = 0
        for key, value in d.items():
            max_depth = max(max_depth, dict_depth(value))
        return max_depth + 1

