def find_last_occurrence(arr, x):
    start = 0
    end = len(arr) - 1

    while start <= end:
        mid = (start + end) // 2

        if arr[mid] < x:
            start = mid + 1
        elif arr[mid] > x:
            end = mid - 1
        else:
            # If mid is the last occurrence or the next element is not equal to x
            if mid == len(arr) - 1 or arr[mid + 1] != x:
                return mid
            else:
                start = mid + 1

    return -1

