def max_volume(sum_of_sides):
    # Check if the sum of sides is less than or equal to 0
    if sum_of_sides <= 0:
        return 0

    # Initialize variables to store the maximum volume and the dimensions of the cuboid
    max_volume = 0
    for length in range(1, sum_of_sides // 3 + 1):
        for width in range(length, (sum_of_sides - length) // 2 + 1):
            height = sum_of_sides - length - width
            if length * width * height > max_volume:
                max_volume = length * width * height

    return max_volume

