def max_occurrences(nums):
    # Create a dictionary to store the count of each number
    counts = {}

    # Iterate through the list and update the count for each number
    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # Find the number with the maximum count
    max_num = max(counts.items(), key=lambda x: x[1])[0]

    return max_num

