    result = 1

    # Calculate n!
    for i in range(1, n + 1):
        result = (result * i) % p

    # Calculate r! and (n-r)!
    for i in range(1, r + 1):
        result = (result * i) % p
    for i in range(1, n - r + 1):
        result = (result * i) % p

    # Compute nCr mod p using the formula (n!/r!(n-r)!)
    return (result * pow(r, p - 2, p)) % p

