def max_profit(prices, k):
    # Initialize variables for dp
    dp = [[[0] * (k + 1) for _ in range(len(prices))] for _ in range(len(prices))]

    # Populate the base cases
    for i in range(1, len(prices)):
        for j in range(1, k + 1):
            dp[i][i][j] = prices[i] - prices[i-1]

    # Fill the DP table
    for i in range(2, len(prices)):
        for j in range(1, k + 1):
            for l in range(i):
                dp[i][l][j] = max(dp[i][l][j], dp[l+1][i][j])
                dp[i][l][j] = max(dp[i][l][j], dp[i-l][l][j-1] + prices[i] - prices[l])

    return dp[len(prices)-1][len(prices)-1][k]

# Test the function with the provided example
assert max_profit([1, 5, 2, 3, 7, 6, 4, 5], 3)

