def is_subset_sum(arr, n, sum):
    # Base case: If sum becomes 0, return True
    if sum == 0:
        return True

    # Base case: If no items left and sum is not 0, return False
    if n == 0 and sum != 0:
        return False

    # If last element is greater than sum, ignore it
    if arr[n-1] > sum:
        return is_subset_sum(arr, n-1, sum)

    # Check if the sum can be achieved by including or excluding the last element
    return is_subset_sum(arr, n-1, sum) or is_subset_sum(arr, n-1, sum - arr[n-1])

# Example usage:
print(is_subset_sum([3, 34, 4, 12, 5, 2], 6, 9))  # Output should be True

