    # Base case: if current_sum equals target_sum, return True
    if current_sum == target_sum:
        return True
    # Base case: if we have checked all elements and current_sum does not match target_sum, return False
    elif index >= len(nums):
        return False
    # Recursive case: include the current element in the subset and check if it leads to the target_sum
    elif nums[index] <= target_sum - current_sum:
        return is_subset_sum(nums, target_sum, current_sum + nums[index], index + 1) or is_subset_sum(nums, target_sum, current_sum, index + 1)
    else:
        # If the current element is greater than the remaining sum needed, skip it
        return is_subset_sum(nums, target_sum, current_sum, index + 1)

