def is_palindrome(n):
    return str(n) == str(n)[::-1]

def largest_palindrome(nums, n):
    # Filter out non-palindromes from the list
    nums = [num for num in nums if is_palindrome(num)]

    # Find the maximum palindrome number
    if nums:
        return max(nums)
    else:
        return None  # Return None if there are no palindromes

# Example usage
print(largest_palindrome([1, 232, 54545, 999991], 4))  # Output: 54545

