def binary_to_integer(binary_tuple):
    # Convert each binary value to its decimal equivalent
    decimal_value = sum(int(bit) * (2 ** index) for index, bit in enumerate(reversed(binary_tuple)))
    return str(decimal_value)

# Test the function with the provided example
print(binary_to_integer((1, 1, 0, 1, 0, 0, 1)))  # Output: '105'

