def permutation_coefficient(n, k):
    # Base cases for p(n, k)
    if k > n or k < 0:
        return 0
    elif k == 0:
        return 1
    else:
        # Recursive formula for calculating p(n, k)
        return n * permutation_coefficient(n - 1, k - 1)

# Test case to verify the correctness of the solution
assert permutation_coefficient(10, 2) == 90

